css:
.relative {
  position: relative
}

.isolation-auto {
  isolation: auto
}

.z-10 {
  z-index: 10
}

.overflow-hidden {
  overflow: hidden
}

.rounded-md {
  border-radius: 0.375rem
}

.border-2 {
  border-width: 2px
}

.border-lime-500 {
  --tw-border-opacity: 1;
  border-color: rgb(132 204 22 / var(--tw-border-opacity))
}

.bg-white {
  --tw-bg-opacity: 1;
  background-color: rgb(255 255 255 / var(--tw-bg-opacity))
}

.px-8 {
  padding-left: 2rem;
  padding-right: 2rem
}

.py-2 {
  padding-top: 0.5rem;
  padding-bottom: 0.5rem
}

.before\:absolute::before {
  content: var(--tw-content);
  position: absolute
}

.before\:-right-full::before {
  content: var(--tw-content);
  right: -100%
}

.before\:-z-10::before {
  content: var(--tw-content);
  z-index: -10
}

.before\:aspect-square::before {
  content: var(--tw-content);
  aspect-ratio: 1 / 1
}

.before\:w-full::before {
  content: var(--tw-content);
  width: 100%
}

.before\:rounded-full::before {
  content: var(--tw-content);
  border-radius: 9999px
}

.before\:bg-lime-500::before {
  content: var(--tw-content);
  --tw-bg-opacity: 1;
  background-color: rgb(132 204 22 / var(--tw-bg-opacity))
}

.before\:transition-all::before {
  content: var(--tw-content);
  transition-property: all;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  transition-duration: 150ms
}

.before\:duration-700::before {
  content: var(--tw-content);
  transition-duration: 700ms
}

.before\:hover\:right-0:hover::before {
  content: var(--tw-content);
  right: 0px
}

.before\:hover\:w-full:hover::before {
  content: var(--tw-content);
  width: 100%
}

.before\:hover\:scale-150:hover::before {
  content: var(--tw-content);
  --tw-scale-x: 1.5;
  --tw-scale-y: 1.5;
  transform: translate(var(--tw-translate-x), var(--tw-translate-y)) rotate(var(--tw-rotate)) skewX(var(--tw-skew-x)) skewY(var(--tw-skew-y)) scaleX(var(--tw-scale-x)) scaleY(var(--tw-scale-y))
}

.before\:hover\:duration-700:hover::before {
  content: var(--tw-content);
  transition-duration: 700ms
}
